import type { MetadataRoute } from "next";
import { QUICK_ACTION_PATHS } from "@/lib/navigation";
import { THEME_COLORS } from "@/lib/theme/theme";

/*
 * Makes the app installable. `id` keeps the install identity stable if the
 * start address ever changes. Shortcuts show up on a long press of the app
 * icon (Android) and in the taskbar jump list (desktop Chrome and Edge).
 * Icons are generated by scripts/generate-icons.mjs.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Wintrarc",
    short_name: "Wintrarc",
    description: "Become the person you said you'd be.",
    lang: "en",
    dir: "ltr",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: THEME_COLORS.dark,
    theme_color: THEME_COLORS.dark,
    categories: ["productivity", "lifestyle", "health"],
    icons: [
      {
        src: "/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    shortcuts: [
      {
        name: "Today",
        short_name: "Today",
        description: "See what is left to do today",
        url: "/",
      },
      {
        name: "New habit",
        short_name: "New habit",
        url: QUICK_ACTION_PATHS.addHabit,
      },
      {
        name: "New task",
        short_name: "New task",
        url: QUICK_ACTION_PATHS.addTask,
      },
      {
        name: "Start focus session",
        short_name: "Focus",
        url: QUICK_ACTION_PATHS.startFocus,
      },
    ],
  };
}
